#include <iostream>
int main() {
  long long n;
  if (!(std::cin >> n) || n < 0 || n > 1000000000) return 1;
  long long reversed = 0;
  for (long long x = n; x > 0; x /= 10) {
    reversed = reversed * 10 + x % 10;
  }
  std::cout << (reversed == n ? "YES" : "NO") << "\n";
}

